   267  static CURLcode ftp_pl_insert_finfo(struct connectdata *conn,
   268                                      struct fileinfo *infop)
   269  {
   270    curl_fnmatch_callback compare;
   271    struct WildcardData *wc = &conn->data->wildcard;
